begin;
create extension if not exists pgtap with schema extensions;
select plan(8);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values ('00000000-0000-0000-0000-000000000030','00000000-0000-0000-0000-000000000000','authenticated','authenticated','publication-admin@example.invalid','','{}','{}',now(),now());
insert into public.resource_registry(id,display_name,lifecycle_state,editorial_status) values ('00000000-0000-0000-0000-000000000301','Eligible','active','approved'),('00000000-0000-0000-0000-000000000302','Unsafe','active','approved'),('00000000-0000-0000-0000-000000000303','Hidden','active','hidden');
insert into public.location_qc_reviews(canonical_resource_id,policy_version,classification_fingerprint,decision,review_snapshot,version,reviewed_by) values ('00000000-0000-0000-0000-000000000301','v1',repeat('a',64),'pilot_eligible','{"submitted_address":"100 Main St","returned_address":"100 Main St, Vancouver, BC","locality":"Vancouver","score":100,"location_descriptor":"parcelpoint","coordinates":{"latitude":49.2,"longitude":-123.1},"program_occupancy_confidence":"supported","conflicts":[],"sensitivity_flags":[]}',1,'00000000-0000-0000-0000-000000000030'),('00000000-0000-0000-0000-000000000302','v1',repeat('b',64),'pilot_eligible','{"submitted_address":"200 Main St","returned_address":"200 Main St","locality":"Vancouver","score":100,"location_descriptor":"parcelpoint","coordinates":{"latitude":49.2,"longitude":-123.2},"program_occupancy_confidence":"supported","conflicts":[],"sensitivity_flags":["confidential"]}',1,'00000000-0000-0000-0000-000000000030');
insert into public.resource_fact_claims(id,resource_id,field_name,proposed_value,risk,recommendation,confidence,engine_version,status,claim_fingerprint) values ('00000000-0000-0000-0000-000000000401','00000000-0000-0000-0000-000000000301','location_occupancy','"100 Main St"'::jsonb,'medium','auto_accept','high','test','observed',repeat('c',64));
insert into public.resource_fact_evidence(claim_id,source_type,source_url,source_authority,extraction_method,independent_key,evidence_fingerprint) values ('00000000-0000-0000-0000-000000000401','official_provider','https://example.invalid/program',95,'test','example.invalid',repeat('d',64));
select is((public.publish_verified_map_pin('00000000-0000-0000-0000-000000000301',1,'00000000-0000-0000-0000-000000000030')).public_map,true,'eligible publishes');
select is((select count(*)::integer from public.resource_locations where resource_id='00000000-0000-0000-0000-000000000301'),1,'one location created');
select is((public.publish_verified_map_pin('00000000-0000-0000-0000-000000000301',1,'00000000-0000-0000-0000-000000000030')).public_map,true,'retry idempotent');
select is((select count(*)::integer from public.resource_locations where resource_id='00000000-0000-0000-0000-000000000301'),1,'no duplicate retry');
select throws_ok($$select public.publish_verified_map_pin('00000000-0000-0000-0000-000000000301',0,'00000000-0000-0000-0000-000000000030')$$,'40001','publication QC version conflict','stale blocked');
select throws_ok($$select public.publish_verified_map_pin('00000000-0000-0000-0000-000000000302',1,'00000000-0000-0000-0000-000000000030')$$,'P0001','publication evidence package is incomplete or unsafe','sensitive blocked');
select is((select count(*)::integer from public.resource_locations where resource_id='00000000-0000-0000-0000-000000000302'),0,'unsafe has no partial location');
select is((select count(*)::integer from public.resource_location_audit where action='publication_changed'),1,'audit written');
select * from finish(); rollback;
